import "@spectrum-web-components/theme/sp-theme.js";
import "@spectrum-web-components/theme/src/themes.js";

import "@spectrum-web-components/banner/sp-banner.js";
import "@spectrum-web-components/theme/src/express/themes.js";

const [uxpMajor, uxpMinor] = require("uxp").versions.uxp.substr(4).split(".");

// Curent SWC components work only for UXP version >=8.0
if (uxpMajor + "." + uxpMinor < 8.0) {
  document.querySelector("body").innerHTML = `
  <h3>Current SWC wrappers are not support for UXP below version 8.0 </h3>
  `;
}
